pub fn NewWrappedIterator(comptime path_type: PathType) type {
        const IteratorType = (if ((path_type == PathType.u16)) IteratorW else Iterator);
        const ResultType = (if ((path_type == PathType.u16)) ResultW else Result);
        return struct {
    iter: IteratorType,

pub inline fn next(self: *@This()) ResultType {
            return self.iter.next();
    }

pub fn init(dir: FD) Self {
            return Self{ .iter = (switch (bun.Environment.os) {
.mac => IteratorType{ .dir = dir, .seek = 0, .index = 0, .end_index = 0, .buf = undefined },
.linux, .freebsd => IteratorType{ .dir = dir, .index = 0, .end_index = 0, .buf = undefined },
.windows => IteratorType{ .dir = dir, .index = 0, .end_index = 0, .first = true, .buf = undefined, .name_data = undefined },
.wasm => IteratorType{ .dir = dir, .cookie = posix.wasi.DIRCOOKIE_START, .index = 0, .end_index = 0, .buf = undefined },
}) };
    }

pub fn setNameFilter(self: *@This(), filter: ?[]const u16) void {
            if (comptime (!bun.Environment.isWindows)) {
                return;
            }
            self.iter.name_filter = filter;
    }
    const Self = @This();
    pub const Error = IteratorError;
};
}

pub fn iterate(client: FD, comptime path_type: PathType) NewWrappedIterator(path_type) {
        return NewWrappedIterator(path_type).init(client);
}
